<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import {matArrowBack,matRefresh,matStop,matDownload} from '@quasar/extras/material-icons'
import {request} from '../lib/api'
import {subscribeEvents,liveConnection,type LiveEvent} from '../lib/live'
import {terminalStates,type Job,type Event} from '../types'
import EvidenceBrowser from '../components/EvidenceBrowser.vue'
import ArtifactGallery from '../components/ArtifactGallery.vue'
const props=defineProps<{id:string}>(),router=useRouter(),job=ref<Job|null>(null),events=ref<Event[]>([]),tab=ref('activity'),loading=ref(true),error=ref(''),historyError=ref(''),hasMore=ref(false),before=ref(''),cancelDialog=ref(false),pending=ref(false)
const evidence=ref<InstanceType<typeof EvidenceBrowser>|null>(null)
const retryDialog=ref(false),retryAuthorized=ref(false);let retryKey=''
async function retry(){if(!terminal.value||!retryAuthorized.value||pending.value)return;const current=scope,id=props.id;pending.value=true;try{if(!retryKey)retryKey=crypto.randomUUID();const next=await request<Job>(`/jobs/${encodeURIComponent(id)}/retry`,{method:'POST',body:{idempotency_key:retryKey},signal:lifetime.signal});if(current!==scope)return;retryDialog.value=false;await router.push('/jobs/'+encodeURIComponent(next.id))}catch(e){if(current===scope&&!lifetime.signal.aborted)error.value=e instanceof Error?e.message:'Retry could not be queued. Check the queue before trying again.'}finally{if(current===scope)pending.value=false}}
const terminal=computed(()=>job.value?terminalStates.has(job.value.state):false)
const connectionLabel=computed(()=>liveConnection.value==='live'?'Live events connected':liveConnection.value==='connecting'?'Connecting live events':'Live events unavailable · refreshing every 15 seconds')
let scope=0,lifetime=new AbortController(),details:AbortController|undefined,history:AbortController|undefined,unsubscribe:(()=>void)|undefined,timer:ReturnType<typeof setInterval>|undefined,refreshTimer:ReturnType<typeof setTimeout>|undefined
function timestamp(v:string|null|undefined){return v?new Date(v).toLocaleString():'Not reported'}
function label(v:string){return v.replaceAll('_',' ')}
function text(e:Event){if(e.message)return e.message;if(typeof e.data?.message==='string')return e.data.message;if(typeof e.data?.state==='string')return 'State changed to '+label(e.data.state);if(typeof e.data?.phase==='string')return 'Phase: '+label(e.data.phase);return label(e.kind)}
async function load(){details?.abort();details=new AbortController();const signal=details.signal,id=props.id;loading.value=true;try{const j=await request<Job>('/jobs/'+encodeURIComponent(id),{signal});if(!signal.aborted&&id===props.id){job.value=j;error.value=''}}catch(e){if(!signal.aborted&&id===props.id)error.value=e instanceof Error?e.message:'Job could not be loaded.'}finally{if(!signal.aborted)loading.value=false}}
async function loadHistory(){history?.abort();history=new AbortController();const signal=history.signal,id=props.id;try{const p=await request<{items:Event[];has_more:boolean}>(`/jobs/${encodeURIComponent(id)}/history?limit=200${before.value?'&before='+encodeURIComponent(before.value):''}`,{signal});if(!signal.aborted&&id===props.id){const live=before.value?[]:events.value;events.value=[...new Map([...p.items,...live].map(e=>[e.seq,e])).values()].sort((a,b)=>BigInt(a.seq)>BigInt(b.seq)?-1:1).slice(0,200);hasMore.value=p.has_more;historyError.value=''}}catch(e){if(!signal.aborted&&id===props.id)historyError.value=e instanceof Error?e.message:'Event history could not be loaded.'}}
function onEvent(e:LiveEvent){if(e.job_id!==props.id)return;if(!before.value){events.value=[e,...events.value.filter(v=>v.seq!==e.seq)].slice(0,200)}clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>{void load();void evidence.value?.refresh()},200)}
function latest(){before.value='';events.value=[];void loadHistory()}
function earlier(){before.value=events.value.at(-1)?.seq??'';events.value=[];void loadHistory()}
async function cancel(){if(!job.value||pending.value)return;const current=scope,id=props.id;pending.value=true;try{const next=await request<Job>(`/jobs/${encodeURIComponent(id)}/cancel`,{method:'POST',body:{},signal:lifetime.signal});if(current!==scope)return;job.value=next;cancelDialog.value=false;error.value='';void loadHistory()}catch(e){if(current===scope&&!lifetime.signal.aborted)error.value=e instanceof Error?e.message:'Cancellation could not be requested.'}finally{if(current===scope)pending.value=false}}
function enter(){scope++;lifetime.abort();lifetime=new AbortController();details?.abort();history?.abort();job.value=null;events.value=[];before.value='';error.value='';historyError.value='';pending.value=false;cancelDialog.value=false;retryDialog.value=false;retryAuthorized.value=false;retryKey='';void load();void loadHistory()}
watch(()=>props.id,enter);watch(()=>liveConnection.value,v=>{if(v==='live'){void load();if(!before.value)void loadHistory()}})
onMounted(()=>{enter();unsubscribe=subscribeEvents(onEvent);timer=setInterval(()=>{if(!loading.value){void load();if(!before.value)void loadHistory()}},15000)})
onBeforeUnmount(()=>{scope++;lifetime.abort();details?.abort();history?.abort();unsubscribe?.();clearInterval(timer);clearTimeout(refreshTimer)})
</script>
<template>
 <q-page class="workspace job-record"><header class="page-header"><div><q-btn flat dense :icon="matArrowBack" label="Job dispatch" class="back-link" @click="router.push('/jobs')"/><p class="page-kicker">Durable job record</p><h1>{{job?.name??'Job record'}}</h1><p class="page-description mono">{{id}}</p></div><div class="row items-center q-gutter-sm"><q-btn flat round :icon="matRefresh" :loading="loading" aria-label="Refresh job record" @click="load();loadHistory()"/><q-btn v-if="job&&!terminal" data-testid="cancel-job" flat color="negative" :icon="matStop" :disable="job.cancel_requested" :label="job.cancel_requested?'Cancellation requested':'Cancel job'" @click="cancelDialog=true"/><q-btn v-if="job&&terminal" data-testid="retry-job" flat label="Retry as new job" @click="retryAuthorized=false;retryDialog=true"/><q-btn v-if="job" flat :icon="matDownload" label="Download report" :href="'/api/jobs/'+encodeURIComponent(id)+'/export'" target="_blank" rel="noopener"/></div></header>
  <div v-if="error" role="alert" class="error-banner">{{error}}<span v-if="job"> Showing the last loaded job record.</span></div><p v-if="loading&&!job" role="status" class="loading-label">Loading the durable job record…</p>
  <template v-if="job"><section class="record-status surface"><div><span class="status-badge" :data-state="job.state">{{label(job.state)}}</span><h2>{{job.phase?label(job.phase):'Phase not reported'}}</h2><p class="helper">{{connectionLabel}}</p></div><dl class="record-counters"><div><dt>Host results</dt><dd>{{job.result_count}}</dd></div><div><dt>Camera evidence</dt><dd>{{job.camera_count}}</dd></div><div><dt>Stream evidence</dt><dd>{{job.stream_count}}</dd></div><div><dt>Inconclusive hosts</dt><dd>{{job.inconclusive_count}}</dd></div></dl><q-linear-progress v-if="!terminal" indeterminate color="primary"/><p v-if="!terminal" class="record-disclaimer helper">No completion percentage or ETA is inferred from requested scope. Evidence appears only when it has been durably imported.</p></section>
   <div v-if="job.error" class="error-banner q-mt-lg" role="alert">{{job.error}}</div><div class="record-layout"><section class="record-main"><q-tabs v-model="tab" align="left" no-caps active-color="dark" indicator-color="dark" class="record-tabs"><q-tab name="activity" label="Activity"/><q-tab name="evidence" label="Evidence"/><q-tab name="images" label="Stored images"/><q-tab name="configuration" label="Configuration snapshot"/></q-tabs><section v-if="tab==='activity'" class="surface activity-panel"><header class="section-heading"><div><h2>{{before?'Earlier events':'Latest events'}}</h2><p class="helper">Up to 200 persisted events per window. IDs remain exact strings.</p></div><q-btn v-if="before" flat label="Back to latest" @click="latest"/></header><p v-if="historyError" class="inline-error" role="alert">{{historyError}}</p><ol v-if="events.length" class="event-timeline"><li v-for="event in events" :key="event.seq"><time>{{timestamp(event.at??event.created_at)}}</time><div><span class="event-kind">{{label(event.kind)}}</span><p>{{text(event)}}</p><small class="mono">#{{event.seq}}</small></div></li></ol><div v-else-if="!historyError" class="resource-empty"><h2>No events in this window</h2><p>Durable job state is shown independently of the live connection.</p></div><footer v-if="hasMore" class="history-footer"><q-btn flat label="Earlier events" @click="earlier"/></footer></section><EvidenceBrowser v-else-if="tab==='evidence'" ref="evidence" :job-id="id"/><ArtifactGallery v-else-if="tab==='images'" :job-id="id" class="surface"/><section v-else class="surface snapshot-panel"><h2>Immutable execution request</h2><p class="helper q-mt-sm">Saved settings and opaque secret references. Editing profiles does not rewrite this job.</p><pre>{{JSON.stringify(job.config,null,2)}}</pre></section></section>
    <aside class="surface record-aside"><span class="section-label">Execution context</span><dl class="detail-list"><div><dt>Requested scope</dt><dd>{{job.config.targets.join(', ')}}</dd></div><div><dt>Scan mode</dt><dd>{{job.config.scan_mode}}</dd></div><div><dt>Priority</dt><dd>{{job.priority}} · lower runs first</dd></div><div><dt>Attempt</dt><dd>{{job.attempt}}</dd></div><div><dt>Queued</dt><dd>{{timestamp(job.created_at)}}</dd></div><div><dt>Started</dt><dd>{{timestamp(job.started_at)}}</dd></div><div><dt>Finished</dt><dd>{{timestamp(job.finished_at)}}</dd></div><div><dt>HTTP proxy</dt><dd>{{job.config.proxy_version_id?'Pinned proxy version':'No explicit proxy selected'}}</dd></div></dl><p class="safe-note">HTTP proxy routing does not cover TCP discovery, raw packets, RTSP, UDP or private media/dependency traffic. Browser views never probe device URLs.</p><p v-if="job.cancel_requested&&!terminal" class="safe-note q-mt-md">Cancellation is a request, not proof the process has stopped. Wait for a terminal outcome.</p><q-btn v-if="job.retry_of" flat dense class="q-mt-lg" label="Original job" :to="'/jobs/'+job.retry_of"/></aside>
   </div></template>
  <q-dialog v-model="retryDialog"><q-card class="confirmation-dialog"><q-card-section><h2>Retry as a new job?</h2><p>Run this scan again with the same settings. The previous results are kept.</p><q-checkbox data-testid="authorize-retry" v-model="retryAuthorized" color="dark" label="Confirm retry."/></q-card-section><q-card-actions align="right"><q-btn flat label="Keep original only" v-close-popup/><q-btn data-testid="confirm-retry" unelevated color="dark" label="Queue authorized retry" :disable="!retryAuthorized||pending" :loading="pending" @click="retry"/></q-card-actions></q-card></q-dialog>
  <q-dialog v-model="cancelDialog"><q-card class="confirmation-dialog"><q-card-section><h2>Cancel this job?</h2><p>The runner must acknowledge process termination before active work becomes canceled. Already stored evidence remains available.</p></q-card-section><q-card-actions align="right"><q-btn flat label="Keep running" v-close-popup/><q-btn data-testid="confirm-cancel" unelevated color="negative" label="Request cancellation" :loading="pending" @click="cancel"/></q-card-actions></q-card></q-dialog>
 </q-page>
</template>
<style scoped>.job-record{max-width:1560px}.job-record h1{overflow-wrap:anywhere;max-width:35ch}.back-link{margin-left:-9px;margin-bottom:20px}.page-description.mono{font-size:12px}.record-status{padding:24px;display:grid;grid-template-columns:1fr 1.4fr;gap:24px}.record-status h2{font-size:24px;text-transform:capitalize;margin-top:18px;margin-bottom:12px}.record-counters{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:0;align-content:center}.record-counters dt{font-size:11px;color:var(--muted)}.record-counters dd{font-size:29px;font-weight:650;margin:8px 0}.record-status>.q-linear-progress,.record-disclaimer{grid-column:1/-1}.record-disclaimer{margin:0}.record-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px;margin-top:28px;align-items:start}.record-main{min-width:0}.record-aside{padding:24px;margin-top:58px}.record-tabs{margin-bottom:18px}.event-timeline{list-style:none;padding:0 24px;margin:0}.event-timeline>li{display:grid;grid-template-columns:150px minmax(0,1fr);gap:22px;border-bottom:1px solid var(--line);padding:22px 0}.event-timeline time{font-size:11px;color:var(--muted);line-height:1.7}.event-timeline p{margin:6px 0;overflow-wrap:anywhere;font-size:13px}.event-kind{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}.event-timeline small{font-size:10px;color:var(--muted)}.history-footer{padding:16px;text-align:center}.snapshot-panel{padding:26px}.snapshot-panel pre{font-size:12px;line-height:1.8;overflow:auto;max-height:650px;margin-bottom:0}.activity-panel .inline-error{padding:20px}@media(max-width:1200px){.record-status{grid-template-columns:1fr}.record-layout{grid-template-columns:1fr}.record-aside{margin-top:0}.record-counters{max-width:650px}}@media(max-width:600px){.record-status{padding:20px}.record-counters{grid-template-columns:1fr 1fr}.event-timeline{padding:0 18px}.event-timeline>li{grid-template-columns:1fr;gap:8px}.snapshot-panel{padding:20px}}</style>
